begin;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id), full_name text not null, email text not null, role text not null check(role in ('admin','supervisor')), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function public.active_user() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and is_active) $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and is_active and role='admin') $$;
create table public.options(id uuid primary key default gen_random_uuid(), kind text not null check(kind in ('waste','unit','facility','status')), label text not null, is_active boolean not null default true, unique(kind,label));
insert into public.options(kind,label) values ('waste','Palm Waste'),('waste','Tree Branches'),('waste','Pruning Waste'),('waste','Dry Leaves'),('waste','Grass and Weeds'),('waste','Mixed Agricultural Waste'),('waste','Other'),('unit','Kilograms (kg)'),('unit','Tonnes'),('unit','Cubic Meters (m³)'),('unit','Bags'),('unit','Piles'),('facility','Office / Site Cabin'),('facility','Worker Accommodation'),('facility','Toilets / Washrooms'),('facility','Storage'),('facility','Water Supply Facility'),('facility','Electrical / Generator Facility'),('facility','Waste Collection Facility'),('facility','Other'),('status','Operational'),('status','Needs Attention'),('status','Under Maintenance'),('status','Out of Service');
create table public.app_settings(id boolean primary key default true check(id), gps_accuracy_meters numeric not null default 20 check(gps_accuracy_meters > 0));
insert into public.app_settings(id) values(true);
create table public.location_verifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),accuracy double precision not null check(accuracy > 0),captured_at timestamptz not null,viewed_at timestamptz,confirmed_at timestamptz,used_at timestamptz,created_at timestamptz not null default now());
create table public.photo_uploads(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),url text not null check(url like 'https://i.ibb.co/%'),used_at timestamptz,created_at timestamptz not null default now());
create sequence public.waste_number;
create sequence public.facility_number;
create sequence public.inspection_number;
create table public.facilities(id uuid primary key default gen_random_uuid(),number text not null unique default ('OFT-'||lpad(nextval('facility_number')::text,6,'0')),name text not null,category text not null,site text not null,description text not null default '',status text not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),assigned_supervisor uuid references profiles(id),remarks text not null default '',archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.waste_reports(id uuid primary key default gen_random_uuid(),number text not null unique default ('COSA-'||lpad(nextval('waste_number')::text,greatest(4,length(currval('waste_number')::text)),'0')),supervisor_id uuid not null references profiles(id),category text not null,quantity numeric not null check(quantity>0),unit text not null,description text not null default '',latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),gps_accuracy_meters double precision not null check(gps_accuracy_meters>0),gps_captured_at timestamptz not null,location_confirmed boolean not null check(location_confirmed),location_confirmed_at timestamptz not null,idempotency_key uuid not null unique,created_at timestamptz not null default now(),check(category<>'Other' or length(trim(description))>0));
create table public.facility_inspections(id uuid primary key default gen_random_uuid(),number text not null unique default ('OFT-I-'||lpad(nextval('inspection_number')::text,6,'0')),facility_id uuid not null references facilities(id),supervisor_id uuid not null references profiles(id),condition text not null,inspection_date date not null,description text not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),gps_accuracy_meters double precision not null check(gps_accuracy_meters>0),gps_captured_at timestamptz not null,location_confirmed boolean not null check(location_confirmed),location_confirmed_at timestamptz not null,idempotency_key uuid not null unique,created_at timestamptz not null default now());
create table public.waste_report_photos(id uuid primary key default gen_random_uuid(),report_id uuid not null references waste_reports(id) on delete cascade,url text not null);
create table public.facility_photos(id uuid primary key default gen_random_uuid(),facility_id uuid not null references facilities(id) on delete cascade,url text not null);
create table public.facility_inspection_photos(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references facility_inspections(id) on delete cascade,url text not null);
create table public.notifications(id uuid primary key default gen_random_uuid(),report_type text not null,record_id uuid not null,recipient_id uuid not null references profiles(id),message text not null,is_read boolean not null default false,created_at timestamptz not null default now());
create table public.delivery_attempts(id uuid primary key default gen_random_uuid(),record_type text not null check(record_type in ('waste','inspection')),record_id uuid not null,channel text not null default 'email',recipient text not null,provider_message_id text,status text not null default 'pending' check(status in ('pending','sent','delivered','failed')),attempts integer not null default 0,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(record_type,record_id));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),record_type text not null,record_id uuid not null,actor_id uuid references profiles(id),action text not null,change_summary jsonb not null,created_at timestamptz not null default now());
create table public.rate_limits(user_id uuid references profiles(id),action text not null,window_start timestamptz not null default date_trunc('minute',now()),hits integer not null default 1,primary key(user_id,action,window_start));
create index waste_supervisor_date on waste_reports(supervisor_id,created_at desc);
create index waste_category_date on waste_reports(category,created_at desc);
create index inspections_supervisor_date on facility_inspections(supervisor_id,created_at desc);
create index inspections_facility_date on facility_inspections(facility_id,created_at desc);
create index facilities_assignee on facilities(assigned_supervisor);
create index notification_recipient on notifications(recipient_id,created_at desc);
create index waste_photo_parent on waste_report_photos(report_id);
create index facility_photo_parent on facility_photos(facility_id);
create index inspection_photo_parent on facility_inspection_photos(inspection_id);
create index delivery_record on delivery_attempts(record_id);
create index location_owner on location_verifications(user_id,created_at);
create index upload_owner on photo_uploads(user_id,created_at);
create function public.capture_location(p_user uuid,p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare rid uuid; threshold numeric; begin
 if not exists(select 1 from profiles where id=p_user and is_active) then raise exception 'Inactive account'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 select gps_accuracy_meters into threshold from app_settings where id=true;
 if (p->>'accuracy')::numeric>threshold or (p->>'captured_at')::timestamptz<now()-interval '5 minutes' or (p->>'captured_at')::timestamptz>now()+interval '10 seconds' then raise exception 'Invalid GPS reading'; end if;
 update location_verifications set used_at=now(),confirmed_at=null where user_id=p_user and used_at is null;
 insert into location_verifications(user_id,latitude,longitude,accuracy,captured_at) values(p_user,(p->>'latitude')::double precision,(p->>'longitude')::double precision,(p->>'accuracy')::double precision,(p->>'captured_at')::timestamptz) returning id into rid;
 return rid;
end $$;
revoke all on function capture_location(uuid,jsonb) from public,anon,authenticated;
grant execute on function capture_location(uuid,jsonb) to service_role;
create function public.take_rate_limit(p_action text,p_max integer) returns boolean language plpgsql security definer set search_path=public as $$ declare n integer; begin if not active_user() then raise exception 'Unauthorized'; end if; insert into rate_limits(user_id,action) values(auth.uid(),p_action) on conflict(user_id,action,window_start) do update set hits=rate_limits.hits+1 returning hits into n; return n <= least(p_max,60); end $$;
create function public.submit_report(p jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare loc location_verifications; rid uuid; num text; v_kind text:=p->>'kind'; photos uuid[]; previous jsonb; threshold numeric;
begin
 if not active_user() then raise exception 'Unauthorized'; end if;
 if v_kind not in ('waste','inspection') then raise exception 'Invalid module'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p->>'idempotency_key',0));
 if v_kind='waste' then select jsonb_build_object('id',id,'number',number,'created_at',created_at) into previous from waste_reports where idempotency_key=(p->>'idempotency_key')::uuid and supervisor_id=auth.uid(); else select jsonb_build_object('id',id,'number',number,'created_at',created_at) into previous from facility_inspections where idempotency_key=(p->>'idempotency_key')::uuid and supervisor_id=auth.uid(); end if;
 if previous is not null then return previous; end if;
 select * into loc from location_verifications where id=(p->>'location_id')::uuid and user_id=auth.uid() for update;
 select gps_accuracy_meters into threshold from app_settings where id=true;
 if loc.id is null or loc.used_at is not null or loc.viewed_at is null or loc.confirmed_at is null or loc.confirmed_at<loc.viewed_at or loc.captured_at<now()-interval '5 minutes' or loc.captured_at>now()+interval '10 seconds' or loc.accuracy>threshold then raise exception 'Capture and confirm a recent accurate GPS location'; end if;
 select array_agg(distinct value::uuid) into photos from jsonb_array_elements_text(p->'photo_ids');
 if coalesce(array_length(photos,1),0) not between 2 and 3 then raise exception 'Two or three distinct photographs required'; end if;
 perform id from photo_uploads where id=any(photos) and user_id=auth.uid() for update;
 if (select count(*) from photo_uploads where id=any(photos) and user_id=auth.uid() and used_at is null)<>array_length(photos,1) then raise exception 'Invalid or already used uploads'; end if;
 if v_kind='waste' then
 if not exists(select 1 from options where kind='waste' and label=p->>'category' and is_active) or not exists(select 1 from options where kind='unit' and label=p->>'unit' and is_active) then raise exception 'Invalid waste type or unit'; end if;
 insert into waste_reports(supervisor_id,category,quantity,unit,description,latitude,longitude,gps_accuracy_meters,gps_captured_at,location_confirmed,location_confirmed_at,idempotency_key) values(auth.uid(),p->>'category',(p->>'quantity')::numeric,p->>'unit',p->>'description',loc.latitude,loc.longitude,loc.accuracy,loc.captured_at,true,loc.confirmed_at,(p->>'idempotency_key')::uuid) returning id,number into rid,num;
 insert into waste_report_photos(report_id,url) select rid,url from photo_uploads where id=any(photos);
 else
 if not exists(select 1 from facilities where id=(p->>'facility_id')::uuid and archived_at is null and (assigned_supervisor=auth.uid() or is_admin())) then raise exception 'Facility not authorized'; end if;
 if not exists(select 1 from options where kind='status' and label=p->>'condition' and is_active) then raise exception 'Invalid condition'; end if;
 if (p->>'inspection_date')::date > (now() at time zone 'Asia/Riyadh')::date then raise exception 'Inspection date cannot be in the future'; end if;
 insert into facility_inspections(facility_id,supervisor_id,condition,inspection_date,description,latitude,longitude,gps_accuracy_meters,gps_captured_at,location_confirmed,location_confirmed_at,idempotency_key) values((p->>'facility_id')::uuid,auth.uid(),p->>'condition',(p->>'inspection_date')::date,p->>'description',loc.latitude,loc.longitude,loc.accuracy,loc.captured_at,true,loc.confirmed_at,(p->>'idempotency_key')::uuid) returning id,number into rid,num;
 insert into facility_inspection_photos(inspection_id,url) select rid,url from photo_uploads where id=any(photos);
 end if;
 update location_verifications set used_at=now() where id=loc.id;
 update photo_uploads set used_at=now() where id=any(photos);
 insert into notifications(report_type,record_id,recipient_id,message) select v_kind,rid,id,num||' submitted by '||(select full_name from profiles where id=auth.uid()) from profiles where role='admin' and is_active;
 insert into delivery_attempts(record_type,record_id,recipient) values(v_kind,rid,'pending configuration');
 return jsonb_build_object('id',rid,'number',num,'created_at',now());
end $$;
create function public.register_facility(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare rid uuid; photos uuid[]; begin
 if not is_admin() then raise exception 'Administrator required'; end if;
 if not exists(select 1 from options where kind='facility' and label=p->>'category' and is_active) or not exists(select 1 from options where kind='status' and label=p->>'status' and is_active) then raise exception 'Invalid category or status'; end if;
 if p->>'assigned_supervisor' is not null and not exists(select 1 from profiles where id=(p->>'assigned_supervisor')::uuid and role='supervisor' and is_active) then raise exception 'Assignee must be an active supervisor'; end if;
 select array_agg(distinct value::uuid) into photos from jsonb_array_elements_text(p->'photo_ids');
 perform id from photo_uploads where id=any(photos) for update;
 if coalesce(array_length(photos,1),0)>3 or (select count(*) from photo_uploads where id=any(photos) and user_id=auth.uid() and used_at is null)<>coalesce(array_length(photos,1),0) then raise exception 'Invalid uploads'; end if;
 insert into facilities(name,category,site,description,status,latitude,longitude,assigned_supervisor,remarks) values(p->>'name',p->>'category',p->>'site',p->>'description',p->>'status',(p->>'latitude')::double precision,(p->>'longitude')::double precision,(p->>'assigned_supervisor')::uuid,p->>'remarks') returning id into rid;
 insert into facility_photos(facility_id,url) select rid,url from photo_uploads where id=any(photos);
 update photo_uploads set used_at=now() where id=any(photos);
 return rid;
end $$;
create function public.claim_delivery(p_record_id uuid,p_record_type text,p_recipient text) returns jsonb language plpgsql security definer set search_path=public as $$ declare d delivery_attempts; begin update delivery_attempts set status='pending',attempts=attempts+1,recipient=p_recipient,updated_at=now() where record_id=p_record_id and record_type=p_record_type and (status='failed' or (status='pending' and (attempts=0 or updated_at<now()-interval '10 minutes'))) returning * into d; if d.id is null then return null; end if; return jsonb_build_object('id',d.id,'attempts',d.attempts); end $$;
create function public.audit_change() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit_logs(record_type,record_id,actor_id,action,change_summary) values(TG_TABLE_NAME,coalesce(new.id,old.id),auth.uid(),TG_OP,jsonb_build_object('before',case when TG_OP='INSERT' then null else to_jsonb(old) end,'after',case when TG_OP='DELETE' then null else to_jsonb(new) end)); if TG_OP='DELETE' then return old; end if; return new; end $$;
create trigger audit_waste after insert or update or delete on waste_reports for each row execute function audit_change();
create trigger audit_facilities after insert or update or delete on facilities for each row execute function audit_change();
create trigger audit_inspections after insert or update or delete on facility_inspections for each row execute function audit_change();
create trigger audit_profiles after insert or update on profiles for each row execute function audit_change();
alter table profiles enable row level security;
alter table options enable row level security;
alter table app_settings enable row level security;
alter table location_verifications enable row level security;
alter table photo_uploads enable row level security;
alter table facilities enable row level security;
alter table waste_reports enable row level security;
alter table facility_inspections enable row level security;
alter table waste_report_photos enable row level security;
alter table facility_photos enable row level security;
alter table facility_inspection_photos enable row level security;
alter table notifications enable row level security;
alter table delivery_attempts enable row level security;
alter table audit_logs enable row level security;
alter table rate_limits enable row level security;
create policy profile_read on profiles for select to authenticated using(active_user() and (id=auth.uid() or is_admin()));
create policy profile_admin on profiles for update to authenticated using(is_admin()) with check(is_admin());
create policy options_read on options for select to authenticated using(active_user());
create policy options_admin on options for all to authenticated using(is_admin()) with check(is_admin());
create policy settings_read on app_settings for select to authenticated using(active_user());
create policy settings_admin on app_settings for update to authenticated using(is_admin()) with check(is_admin());
create policy facility_read on facilities for select to authenticated using(active_user() and (is_admin() or (assigned_supervisor=auth.uid() and archived_at is null)));
create policy facility_admin_update on facilities for update to authenticated using(is_admin()) with check(is_admin());
create policy waste_read on waste_reports for select to authenticated using(active_user() and (supervisor_id=auth.uid() or is_admin()));
create policy waste_admin_update on waste_reports for update to authenticated using(is_admin()) with check(is_admin());
create policy waste_admin_delete on waste_reports for delete to authenticated using(is_admin());
create policy inspection_read on facility_inspections for select to authenticated using(active_user() and (supervisor_id=auth.uid() or is_admin()));
create policy inspection_admin_update on facility_inspections for update to authenticated using(is_admin()) with check(is_admin());
create policy inspection_admin_delete on facility_inspections for delete to authenticated using(is_admin());
create policy waste_photos_read on waste_report_photos for select to authenticated using(exists(select 1 from waste_reports where id=report_id));
create policy facility_photos_read on facility_photos for select to authenticated using(exists(select 1 from facilities where id=facility_id));
create policy inspection_photos_read on facility_inspection_photos for select to authenticated using(exists(select 1 from facility_inspections where id=inspection_id));
create policy notification_read on notifications for select to authenticated using(is_admin() and recipient_id=auth.uid());
create policy notification_update on notifications for update to authenticated using(is_admin() and recipient_id=auth.uid()) with check(is_admin() and recipient_id=auth.uid());
create policy delivery_read on delivery_attempts for select to authenticated using(active_user() and (is_admin() or exists(select 1 from waste_reports where id=record_id and supervisor_id=auth.uid()) or exists(select 1 from facility_inspections where id=record_id and supervisor_id=auth.uid())));
create policy audit_read on audit_logs for select to authenticated using(is_admin());
revoke all on all tables in schema public from anon;
revoke insert,update,delete on location_verifications,photo_uploads,delivery_attempts,audit_logs,rate_limits from authenticated;
revoke insert on waste_reports,facility_inspections,facilities,waste_report_photos,facility_inspection_photos,facility_photos,profiles,notifications from authenticated;
revoke all on function claim_delivery(uuid,text,text) from public,anon,authenticated;
grant execute on function claim_delivery(uuid,text,text) to service_role;
revoke all on function submit_report(jsonb),register_facility(jsonb),take_rate_limit(text,integer) from public,anon;
grant execute on function submit_report(jsonb),register_facility(jsonb),take_rate_limit(text,integer) to authenticated;
revoke all on function audit_change() from public,anon,authenticated;
grant usage on schema public to authenticated;
grant select on profiles,options,app_settings,facilities,waste_reports,facility_inspections,waste_report_photos,facility_photos,facility_inspection_photos,notifications,delivery_attempts,audit_logs to authenticated;
revoke update on profiles,waste_reports,facility_inspections,facilities,notifications from authenticated;
grant update(is_active,updated_at) on profiles to authenticated;
grant update(category,quantity,unit,description) on waste_reports to authenticated;
grant update(condition,description) on facility_inspections to authenticated;
grant update(name,category,site,description,status,latitude,longitude,assigned_supervisor,remarks,archived_at,updated_at) on facilities to authenticated;
grant update(is_read) on notifications to authenticated;
grant delete on waste_reports,facility_inspections to authenticated;
grant insert,update,delete on options to authenticated;
grant update(gps_accuracy_meters) on app_settings to authenticated;
commit;
